contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depAmt, uint colAmt) public payable {
        require(depAmt > 0);
        require(address(this).balance >= depAmt);

        uint balBeforeDep = c.balances(address(this));
        uint cBalBeforeDep = address(c).balance;
        c.Deposit{value: depAmt}();
        uint balAfterDep = c.balances(address(this));
        uint cBalAfterDep = address(c).balance;
        assert(balAfterDep == balBeforeDep + depAmt && cBalAfterDep == cBalBeforeDep + depAmt);

        bool reverted;
        uint balBeforeCollect = c.balances(address(this));
        uint cBalBeforeCollect = address(c).balance;
        uint thisBalBeforeCollect = address(this).balance;
        try c.Collect(colAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balances(address(this)) == balBeforeCollect - colAmt);
            assert(address(c).balance == cBalBeforeCollect - colAmt);
            assert(address(this).balance == thisBalBeforeCollect + colAmt);
        } else {
            assert(c.balances(address(this)) == balBeforeCollect);
            assert(address(c).balance == cBalBeforeCollect);
            assert(address(this).balance == thisBalBeforeCollect);
        }
    }

    receive() external payable {}
}

