contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        require(depositAmount > 0, "deposit must be positive");
        require(collectAmount == depositAmount, "collect must equal deposit");

        // Read before-state
        uint callerBalBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        // Prepare MinSum to allow collect
        c.SetMinSum(0);
        c.Initialized();

        // Perform deposit
        c.Deposit{value: depositAmount}();

        // Perform collect of the same amount (both should succeed)
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // After-state
        uint callerBalAfter = c.balances(address(this));
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        // Rule: if both Deposit and Collect succeeded, state returns to before-values
        assert(
            collectReverted ||
            (callerBalAfter == callerBalBefore &&
             cBalAfter == cBalBefore &&
             thisBalAfter == thisBalBefore)
        );
    }
}
